#!/bin/sh
# 强符号覆盖弱符号：可替换的默认实现
# 期望输出见 expected_output（本机 MinGW 工具链真实执行捕获）

cat > lib_default.c << 'EOF'
__attribute__((weak)) int config_value = 0;   /* 弱符号：可被覆盖的默认值 */

int get_config(void)
{
    return config_value;
}
EOF

cat > user.c << 'EOF'
int config_value = 42;      /* 强符号：覆盖库里的弱定义 */
EOF

cat > main.c << 'EOF'
#include <stdio.h>

int get_config(void);

int main(void)
{
    printf("config = %d\n", get_config());
    return 0;
}
EOF

gcc -c lib_default.c -o lib_default.o
nm lib_default.o     # config_value 显示为 W/V：弱符号
gcc -c user.c -o user.o
gcc -c main.c -o main.o
gcc main.o user.o lib_default.o -o app   # 强符号胜出
./app
